solution:
fn greet(name: Option[Str]) -> Str {
  if let Some(n) = name {
    return "Hello, " + n + "!";
  } else {
    return "Hello, Guest!";
  }
}

fn double_if_positive(num: Option[Int]) -> Option[Int] {
  if let Some(n) = num {
    if n > 0 {
      return Some(n * 2);
    }
  }
  return None;
}

fn main() -> Int {
  let msg = greet(Some("Alice"));
  return msg.len();
}
